import sys,json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]));sys.path.insert(0,str(Path(__file__).resolve().parent))
from gongbi_training.runtime import configure,LAB
configure()
import torch,numpy as np
from PIL import Image,ImageDraw,ImageFont
from gongbi_training.scene_objects import scene_metrics
from gongbi_training.scene_object_reference import sparse_scene_reference
from guohua_scene_mapping_fix_20261116 import ROOT,PREV,OLD,NEW,read,write,sha
ARMS=['conflicted_control','mapping_fixed'];COLORS=np.array([[232,235,225],[183,134,75],[65,149,91],[145,157,170]],'uint8')
def main():
 res=read(ROOT/'results.json');p=res['protocol'];ds=read(ROOT/'dataset_manifest.json');refs=read(ROOT/'references.json');assert sha(ROOT/'dataset_manifest.json')==p['dataset_sha256'];assert sha(ROOT/'references.json')==p['reference_sha256'];assert sha(Path(__file__).with_name('guohua_scene_mapping_fix_20261116.py'))==p['script_sha256'];assert sha(Path(__file__).resolve().parents[1]/'gongbi_training/source_scene_mapping.py')==p['mapping_module_sha256'];assert sha(PREV/'results.json')==p['conflicted_control_results_sha256'];assert sha(PREV/'scene_plus_line.pt')==p['conflicted_control_sha256'];assert sha(ROOT/'mapping_fixed.pt')==res['checkpoint_sha256'];assert sha(OLD/'results.json')==p['old_results_sha256'];(ROOT/'views').mkdir(exist_ok=True)
 state=torch.load(ROOT/'mapping_fixed.pt',map_location='cpu',weights_only=False)['model'];oldstate=torch.load(OLD/'expanded_control.pt',map_location='cpu',weights_only=False)['model'];assert all(torch.equal(v,state[k]) for k,v in oldstate.items() if k.startswith('encoder.'))
 byid={r['id']:r for r in ds['records']};manual={c['id']:c for c in refs['photo_cases']+refs['video_cases']};records=[];local=[];hcase=next(c for c in read(LAB/'guohua_boundary_reference_20261116/reviewed_references.json')['cases'] if c['id']=='H_14');manual['H_14']=hcase
 for r in res['records']:
  if r['split']=='validation_named':continue
  ident=r['id'];im=Image.open(r['image']).convert('RGB');im.save(ROOT/'views'/(ident+'_input.png'));paths={}
  if ident in manual:target,_=sparse_scene_reference(manual[ident]['size'],manual[ident]['regions'])
  else:assert sha(byid[ident]['target'])==byid[ident]['target_sha256'];target=np.array(Image.open(byid[ident]['target']))
  ref=np.full((im.height,im.width,3),[248,242,224],dtype='uint8');ref[target!=255]=COLORS[target[target!=255]];Image.fromarray(ref).save(ROOT/'views'/(ident+'_reference.png'))
  for a in ARMS:
   pred=np.load(ROOT/'predictions'/(ident+'_'+a+'.npz'))['prediction'];Image.fromarray(COLORS[pred]).save(ROOT/'views'/(ident+'_'+a+'.png'));paths[a]='views/'+ident+'_'+a+'.png'
   if a=='conflicted_control':assert np.array_equal(pred,np.load(PREV/'predictions'/(ident+'_scene_plus_line.npz'))['prediction'])
   if r['scores']:assert scene_metrics(target,pred)['confusion']==r['scores'][a]['confusion']
  records.append(dict(id=ident,split=r['split'],work_group=r['work_group'],input='views/'+ident+'_input.png',reference='views/'+ident+'_reference.png',predictions=paths))
 for c in manual.values():
  rs=[]
  for r in c['regions']:
   if r['kind']!='core_polygon' or r['object']=='unknown':continue
   cid={'open_scene':0,'rock':1,'tree':2,'other_object':3}[r['object']];mask=Image.new('L',tuple(c['size']),0);ImageDraw.Draw(mask).polygon([tuple(x) for x in r['points']],fill=255);m=np.array(mask)>0;rs.append(dict(name=r['name'],object=r['object'],scores={a:float((np.load(ROOT/'predictions'/(c['id']+'_'+a+'.npz'))['prediction'][m]==cid).mean()) for a in ARMS}))
  local.append(dict(id=c['id'],split=next(r['split'] for r in records if r['id']==c['id']),regions=rs))
 write('report_data.json',dict(records=records,aggregates=res['aggregates'],user=res['user_foliage_recall'],local=local,stress=res['photometric_stress'],audit=read(ROOT/'supervision_conflict_audit.json')))
 def board(rows,name):
  b=Image.new('RGB',(1440,len(rows)*350+65),'#f4f1e8');d=ImageDraw.Draw(b);font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18)
  for i,r in enumerate(rows):
   for j,(path,title) in enumerate([(r['input'],'原图'),(r['reference'],'本轮场景参考'),(r['predictions']['conflicted_control'],'冻结：冲突监督对照'),(r['predictions']['mapping_fixed'],'修正源映射的候选')]):
    im=Image.open(ROOT/path);im.thumbnail((346,280));b.paste(im,(j*360+6,i*350+35));d.text((j*360+6,i*350+5),title,font=font,fill='#294735')
   d.text((6,i*350+320),r['id']+' / '+r['split'],font=font,fill='#79523a')
  d.text((6,len(rows)*350+4),'浅灰绿=空景，棕=山石，绿=树木，灰蓝=其他；参考米色=未知。对象分区非墨带/线稿。',font=font,fill='#79523a');b.save(ROOT/name,quality=94)
 board(records[:1],'known_case.jpg');board([r for r in records if r['split']=='photo_holdout'],'work_holdout.jpg')
 select=read(NEW/'selection_before_download.json');reserved={Path(p).stem for p in select['reserved_paths']};assert not any(x.stem in reserved for x in (NEW/'raw').glob('*.jpg'))
 checks=read(ROOT/'pretrain_checks.json');checks.update(all_hashes_match=True,source_targets_match_new_manifest=True,old_control_predictions_bit_identical=True,old_artifacts_unchanged=True,encoders_still_frozen=True,raw_metrics_recomputed_same_corrected_taxonomy=True,reserved_groups_untouched=True,model_adopted=False,expert_truth=False,independent_validation=False,robot_connected=False);write('verification.json',checks)
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>修正四类监督冲突：源标签映射对照</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#294735;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:29px}.note{padding:15px;background:#fff8e8;border-left:5px solid #b77e45}.warn{color:#8b5035}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{min-width:0;background:#fffdf8;padding:10px;border:1px solid #d2d8ca}img{max-width:100%;height:auto;display:block;margin:auto}select{width:650px;max-width:100%;font:inherit;padding:8px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #d3d8ca}a{color:#236b61}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:24px}}</style><main><small>2026-11-16 · 源标签映射修正 · 离线候选</small><h1>先消除空景与“其他”的相反监督</h1><p class="note">此前四类迁移存在数据设计错误：旧三类的“其他”混有水面、云天和其他对象，不能整体迁为四类“其他对象”。约676万旧训练像素因此与新增空景定义冲突。本轮保留旧报告，直接从原始源标签重建四类目标；不把旧冲突候选继续用于后续四类训练。</p><p>源编号1/4/10按本项目空景合并为0，2/13为山石1，3为树木2，其余已标具名对象为3；源0/255仍是未知，绝不自动变成背景。依据为公开类别表、源图/标签叠图和五个助手空景参考核心交叉检查，并非官方CLPD全量专家认证。水、云、天的细分不在本轮合并任务中。</p><h2>1. 监督冲突的实际证据</h2><details><summary>展开原图与源编号覆盖区域</summary><img src="source_code_audit.jpg"></details><p>叠图粉色仅表示选中的源编号，并非皴笔。五个新图空景参考核心都落在源4/10区域；这些区域在上一轮被错误监督为“其他对象”。源1在抽查图中覆盖水面／空景。粗语义边界仍可能有错，不能直接当精确墨带。</p><p id="summary" class="note"></p><h2>2. 同预算、同初始化的映射对照</h2><p>候选与冻结的上一轮scene_plus_line共用初始化、随机种子、图像采样、增强、256步预算和损失，唯一修改是原始粗标签到四类的映射。对照权重未重训，重新推理与原缓存逐像素一致。没有加入新纸色增强，以隔离映射修正作用。</p><div class="scroll"><table><thead><tr><th>同一修正后参考</th><th>模型</th><th>四类平均IoU</th><th>空景IoU</th><th>山石IoU</th><th>树木IoU</th></tr></thead><tbody id="metrics"></tbody></table></div><p class="warn">两组均在同一套修正后四类参考上重算。历史69.2%使用不同的“其他”合并和平均口径，不能与本表直接相减。旧14图、旧12图仍只是已知作品回归，粗标注成绩也不是专家准确率、皴法辨识或完整笔画质量。</p><h2>3. 未进对象训练的新作品组</h2><img src="work_holdout.jpg"><div class="scroll"><table><thead><tr><th>模型</th><th>空景参考召回</th><th>山石参考召回</th><th>树木参考召回</th></tr></thead><tbody id="holdout"></tbody></table></div><p>zhao-ji_autumn-colors两图同属一个文件名作品候选组，已查看原图并由助手选区，但未进入对象训练；这是开发留出，不是新盲测、专家认证或已认证新作者测试。没有根据其分数调参、改阈值或重训。</p><h2>4. 已知用户案例</h2><img src="known_case.jpg"><p id="foliage"></p><p>H_14不进训练，已反复查看，仅作已知回归。树叶核心使用原1,647像素参考，非叶片墨带边界。留白山面与前景岩面另在逐区域表展示，不能只选变好的部分。</p><h2>5. 全部原始输出</h2><select id="case"></select><p id="scope"></p><div class="grid"><div class="card"><b>原图</b><img id="input"></div><div class="card"><b>源粗参考／助手稀疏参考</b><img id="reference"></div><div class="card"><b>冻结的冲突监督对照</b><img id="conflicted_control"></div><div class="card"><b>映射修正候选</b><img id="mapping_fixed"></div></div><p id="refnote">参考不是完整对象边界真值。浅灰绿=空景，棕=山石，绿=树木，灰蓝=其他对象，参考米色=未标。预测未用参考蒙版修饰；对象区域不能直接当墨迹。</p><h2>6. 各处成对参考与模型诊断</h2><p>已保存7个图像中的空景—对象内部成对参考，不增加作品数量。train_photo/train_video为样本内拟合；photo_holdout为开发作品留出；H_14为已知案例。未知和轮廓走廊不作监督或计分。</p><div class="scroll"><table><thead><tr><th>图像与用途</th><th>助手参考</th><th>冲突监督对照</th><th>映射修正候选</th></tr></thead><tbody id="local"></tbody></table></div><h2>7. 纸色与亮度的固定离线压力检查</h2><div class="scroll"><table><thead><tr><th>同一留出图／扰动</th><th>对照：空景／山石召回</th><th>修正：空景／山石召回</th></tr></thead><tbody id="stress"></tbody></table></div><p>original、warm、dim、bright只是对两张留出图作固定颜色/亮度扰动，几何和参考不变。它们不是新作品、真实采集光照或新增真值，没有用于训练，也未据结果挑选权重。</p><h2>8. 当前能力边界</h2><p>本轮完成映射错误修复、同预算候选训练与回归检查，没有自动替换认可绘画版本。对象、皴法均未通过独立验收，树木画法训练保持关闭，未连接机械臂。两组预留作品47条路径仍仅有元数据、未下载或预览。</p><p><a href="protocol.json">冻结训练协议</a> · <a href="supervision_conflict_audit.json">冲突像素与证据</a> · <a href="paired_reference_manifest.json">成对参考清单</a> · <a href="results.json">原始结果</a> · <a href="verification.json">完整验证</a></p><p>来源：<a href="https://github.com/shengbei4980/ShanShuiSeg#分割类别--classes">公开14类编号表</a>；<a href="https://huggingface.co/datasets/Rane7/CLP_dataset">CLPD数据来源</a>。类别表与抽样核查均不能替代逐区域专家验证。</p></main><script>let D;const A=['conflicted_control','mapping_fixed'],N=['冻结冲突对照','映射修正候选'],$=s=>document.getElementById(s),pct=x=>x===null?'无参考':(x*100).toFixed(1)+'%';function show(){let r=D.records[$('case').selectedIndex];$('input').src=r.input;$('reference').src=r.reference;for(let a of A)$(a).src=r.predictions[a];$('scope').textContent=r.id+' / '+r.split+' / '+r.work_group}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of d.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').onchange=show;show();$('summary').textContent='同一开发留出空景参考召回：'+A.map((a,i)=>N[i]+' '+pct(d.aggregates.photo_holdout[a].recall[0])).join('；')+'。数字来自助手参考，仍需看山石、树叶及跨作品误判。';$('foliage').textContent='原有树叶核心召回：'+A.map((a,i)=>N[i]+' '+pct(d.user[a])).join('；');for(let [s,t] of [['new_test','已知14图'],['old_named_regression','旧12图／1作品组']])for(let [i,a] of A.entries()){let v=d.aggregates[s][a],tr=document.createElement('tr');tr.innerHTML='<td>'+t+'</td><td>'+N[i]+'</td>'+[v.mean_iou,v.iou[0],v.iou[1],v.iou[2]].map(x=>'<td>'+pct(x)+'</td>').join('');$('metrics').append(tr)}for(let [i,a] of A.entries()){let v=d.aggregates.photo_holdout[a],tr=document.createElement('tr');tr.innerHTML='<td>'+N[i]+'</td>'+[v.recall[0],v.recall[1],v.recall[2]].map(x=>'<td>'+pct(x)+'</td>').join('');$('holdout').append(tr)}for(let c of d.local)for(let r of c.regions){let tr=document.createElement('tr');tr.innerHTML='<td>'+c.id+' / '+c.split+'</td><td>'+r.name+' / '+r.object+'</td>'+A.map(a=>'<td>'+pct(r.scores[a])+'</td>').join('');$('local').append(tr)}for(let r of d.stress){let tr=document.createElement('tr');tr.innerHTML='<td>'+r.id+' / '+r.variant+'</td>'+A.map(a=>'<td>'+pct(r.scores[a].recall[0])+' / '+pct(r.scores[a].recall[1])+'</td>').join('');$('stress').append(tr)}window.reportReady=true});</script></html>'''
 page=page.replace('参考不是完整对象边界真值。','稀疏／粗参考，无完整对象边界真值。')
 (ROOT/'index.html').write_text(page,encoding='utf8')
 base=Path(__file__).with_name('serve_guohua_objects_v2_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_scene4_mapping_fix_20261116');a=base.index('ALLOWED={');b=base.index('\nALLOWED.update',a);base=base[:a]+"ALLOWED={'index.html','source_code_audit.jpg','known_case.jpg','work_holdout.jpg','report_data.json','protocol.json','supervision_conflict_audit.json','paired_reference_manifest.json','results.json','verification.json'}"+base[b:];(ROOT/'serve_report.py').write_text(base.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8')
 checker=Path(__file__).with_name('check_guohua_objects_v2_view_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_scene4_mapping_fix_20261116').replace(')==27',')==37').replace('range(27)','range(37)').replace(')==6',')==4').replace(';assert js("document.querySelectorAll(\'#works tr\').length")==4','').replace('work_metrics_four_rows=True,','').replace('all27_observations_switch_and_load','all37_observations_switch_and_load').replace('metrics_six_rows','metrics_four_rows').replace("['protocol.json','results.json','selection_before_download.json','source_checked_cunfa_concepts.json','verification.json']","['protocol.json','results.json','supervision_conflict_audit.json','paired_reference_manifest.json','verification.json']").replace("'expanded_control.pt','line_aware_aug.pt','../expanded_control.pt','predictions/H_14_expanded_control.npz'","'mapping_fixed.pt','../mapping_fixed.pt','predictions/H_14_mapping_fixed.npz'")
 checker=checker.replace("assert requests.post(url,timeout=5).status_code==405","assert js('document.querySelectorAll(\"#holdout tr\").length')==2\n assert js('document.querySelectorAll(\"#stress tr\").length')==8\n assert js('document.querySelectorAll(\"#local tr\").length')==35\n assert requests.post(url,timeout=5).status_code==405")
 (ROOT/'check_report.py').write_text(checker.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8');print(json.dumps(checks),flush=True)
if __name__=='__main__':main()
